import axios from "axios";
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addToCart } from "../Redux/Slice";
import "../style/product.css";

export default function Products() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  const dispatch = useDispatch();
  const navigate = useNavigate();

  // =========================
  // REDUX CART
  // =========================

  const cartItems = useSelector(
    (state) => state.cart.items
  );

  // =========================
  // FETCH PRODUCTS
  // =========================

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      const response = await axios.get(
        "http://localhost:5000/api/v1/products",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      console.log("Products:", response.data);

      setProducts(response.data.data || []);
    } catch (error) {
      console.error(
        error.response?.data || error.message
      );

      setError(
        error.response?.data?.message ||
          "Unable to load products."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // =========================
  // SEARCH
  // =========================

  const filteredProducts = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    if (!keyword) {
      return products;
    }

    return products.filter((item) =>
      item.name?.toLowerCase().includes(keyword)
    );
  }, [products, search]);

  // =========================
  // STOCK
  // =========================

  const getStock = (item) => {
    return Number(
      item.quantity ?? item.stock ?? 0
    );
  };

  const inStock = products.filter(
    (item) => getStock(item) > 10
  ).length;

  const lowStock = products.filter((item) => {
    const stock = getStock(item);

    return stock > 0 && stock <= 10;
  }).length;

  const outOfStock = products.filter(
    (item) => getStock(item) <= 0
  ).length;

  // =========================
  // PRODUCT STATUS
  // =========================

  const getStatus = (stock) => {
    if (stock <= 0) {
      return {
        text: "Out of Stock",
        className: "status-out",
      };
    }

    if (stock <= 10) {
      return {
        text: "Low Stock",
        className: "status-low",
      };
    }

    return {
      text: "In Stock",
      className: "status-good",
    };
  };

  return (
    <div className="products-page">

      {/* =================================
          HEADER
      ================================= */}

      <div className="products-header">

        <div>
          <span className="products-eyebrow">
            PRODUCT MANAGEMENT
          </span>

          <h1>
            Products
          </h1>

          <p>
            Manage your store products,
            pricing and inventory.
          </p>
        </div>

        <button
          className="add-product-button"
          onClick={() =>
            navigate("/add-product")
          }
        >
          <span>+</span>
          Add Product
        </button>

      </div>


      {/* =================================
          STATS
      ================================= */}

      <div className="products-stats">

        <div className="stat-card">

          <div className="stat-icon blue">
            <span>▦</span>
          </div>

          <div>
            <p>Total Products</p>
            <h3>{products.length}</h3>
          </div>

        </div>


        <div className="stat-card">

          <div className="stat-icon green">
            <span>✓</span>
          </div>

          <div>
            <p>In Stock</p>
            <h3>{inStock}</h3>
          </div>

        </div>


        <div className="stat-card">

          <div className="stat-icon orange">
            <span>!</span>
          </div>

          <div>
            <p>Low Stock</p>
            <h3>{lowStock}</h3>
          </div>

        </div>


        <div className="stat-card">

          <div className="stat-icon purple">
            <span>🛒</span>
          </div>

          <div>
            <p>Cart Items</p>
            <h3>{cartItems.length}</h3>
          </div>

        </div>

      </div>


      {/* =================================
          PRODUCT SECTION
      ================================= */}

      <div className="product-section">

        {/* TOOLBAR */}

        <div className="product-toolbar">

          <div>
            <h2>
              Product List
            </h2>

            <span>
              {filteredProducts.length} products
            </span>
          </div>


          <div className="product-search">

            <span>
              ⌕
            </span>

            <input
              type="text"
              placeholder="Search product..."
              value={search}
              onChange={(e) =>
                setSearch(e.target.value)
              }
            />

            {search && (
              <button
                className="clear-search"
                onClick={() => setSearch("")}
              >
                ×
              </button>
            )}

          </div>

        </div>


        {/* =================================
            LOADING
        ================================= */}

        {loading && (
          <div className="products-loading">

            <div className="loading-spinner"></div>

            <p>
              Loading products...
            </p>

          </div>
        )}


        {/* =================================
            ERROR
        ================================= */}

        {!loading && error && (
          <div className="products-error">

            <div className="error-symbol">
              !
            </div>

            <div>
              <strong>
                Unable to load products
              </strong>

              <p>
                {error}
              </p>
            </div>

            <button
              onClick={fetchProducts}
            >
              Retry
            </button>

          </div>
        )}


        {/* =================================
            EMPTY
        ================================= */}

        {!loading &&
          !error &&
          products.length === 0 && (

            <div className="products-empty">

              <div className="empty-symbol">
                ▦
              </div>

              <h3>
                No products available
              </h3>

              <p>
                Start by adding your first
                product to the catalog.
              </p>

              <button
                className="add-product-button"
                onClick={() =>
                  navigate("/add-product")
                }
              >
                <span>+</span>
                Add Product
              </button>

            </div>
          )}


        {/* =================================
            PRODUCT TABLE
        ================================= */}

        {!loading &&
          !error &&
          products.length > 0 && (

            filteredProducts.length > 0 ? (

              <div className="product-table-wrapper">

                <table className="product-table">

                  <thead>
                    <tr>

                      <th>
                        PRODUCT
                      </th>

                      <th>
                        PRICE
                      </th>

                      <th>
                        STOCK
                      </th>

                      <th>
                        STATUS
                      </th>

                      <th>
                        ACTION
                      </th>

                    </tr>
                  </thead>


                  <tbody>

                    {filteredProducts.map((item) => {

                      const stock = getStock(item);

                      const status =
                        getStatus(stock);

                      const isInCart =
                        cartItems.some(
                          (cartItem) =>
                            cartItem.id === item.id
                        );

                      return (

                        <tr key={item.id}>

                          {/* PRODUCT */}

                          <td>

                            <div className="table-product">

                              <div className="table-image">

                                <img
                                  src={
                                    item.image ||
                                    "https://via.placeholder.com/100x100?text=No+Image"
                                  }
                                  alt={
                                    item.name ||
                                    "Product"
                                  }
                                />

                              </div>


                              <div className="table-product-info">

                                <strong>
                                  {item.name ||
                                    "Unnamed Product"}
                                </strong>

                                <span>
                                  ID #{item.id}
                                </span>

                              </div>

                            </div>

                          </td>


                          {/* PRICE */}

                          <td>

                            <span className="table-price">
                              ₹
                              {Number(
                                item.price || 0
                              ).toLocaleString(
                                "en-IN"
                              )}
                            </span>

                          </td>


                          {/* STOCK */}

                          <td>

                            <span className="table-stock">

                              {stock > 0
                                ? `${stock} units`
                                : "0 units"}

                            </span>

                          </td>


                          {/* STATUS */}

                          <td>

                            <span
                              className={`product-status ${status.className}`}
                            >

                              <span className="status-circle"></span>

                              {status.text}

                            </span>

                          </td>


                          {/* ACTION */}

                          <td>

                            <button
                              className={`table-cart-button ${
                                isInCart
                                  ? "added"
                                  : ""
                              }`}
                              disabled={
                                isInCart ||
                                stock <= 0
                              }
                              onClick={() =>
                                dispatch(
                                  addToCart(item)
                                )
                              }
                            >

                              {isInCart
                                ? "✓ Added"
                                : stock <= 0
                                ? "Unavailable"
                                : "+ Add to Cart"}

                            </button>

                          </td>

                        </tr>
                      );
                    })}

                  </tbody>

                </table>

              </div>

            ) : (

              /* NO SEARCH RESULT */

              <div className="no-results">

                <div className="no-results-icon">
                  ⌕
                </div>

                <h3>
                  No products found
                </h3>

                <p>
                  Try searching with a
                  different product name.
                </p>

                <button
                  onClick={() => setSearch("")}
                >
                  Clear Search
                </button>

              </div>

            )
          )}

      </div>


      {/* =================================
          FOOTER INFO
      ================================= */}

      {!loading &&
        !error &&
        products.length > 0 && (

          <div className="products-footer-info">

            <span>
              Showing
              <strong>
                {" "}
                {filteredProducts.length}
              </strong>
              {" "}of{" "}
              <strong>
                {products.length}
              </strong>
              {" "}products
            </span>

            <span>
              ShopNest Product Management
            </span>

          </div>
        )}

    </div>
  );
}
